// The attempt and its pinned prompt, read from storage. The source version is loaded next, by the
// Sources sub-workflow, from storage only (never refetched) and verified against its ID.
const ctx = $json.result;
if (!ctx) return [{ json: { missing: true } }];
return [{ json: { store: ctx.store, version: ctx.source_version } }];

// Only explicitly safe validation errors pass through. Anything else (a database or network error) can
// carry private connection details, so it becomes a bounded category with this execution as reference.
const m = String($json.error?.message ?? $json.error ?? '').replace(/ \[line \d+\]$/, '');
const safe = /^(not-found|hash-mismatch|invalid-bundle|invalid-request): [\w .,@:'()-]{0,200}$/.test(m);
return [{ json: { loadError: safe ? m : `source-unavailable (execution ${$execution.id})` } }];

// Decides this run's single action from the stored attempt state, so every step is idempotent:
// call the model once, reuse saved output, or stop. Source and model text stay data, never instructions.
const crypto = require('crypto');
const ctx = $('Read attempt').first().json.result;
const pinned = $json;
const loaded = pinned.bundle ? { sourceSha256: pinned.sha256, sourceChars: pinned.bundle.text.length, sourceTitle: pinned.bundle.title,
  medium: pinned.bundle.medium, textSource: pinned.bundle.textSource, sourceWarnings: pinned.warnings ?? [] } : {};
const base = ctx ? { attempt: ctx.attempt, mode: ctx.mode, fakeBehaviour: ctx.fake_behaviour,
  trace: { sourceVersion: ctx.source_version, store: ctx.store, promptIdentity: ctx.prompt_identity, ...loaded } } : {};
const stop = (reason) => [{ json: { ...base, action: 'stop', reason } }];
const fail = (reason) => [{ json: { ...base, action: 'fail', reason } }];
if (!ctx) return [{ json: { action: 'stop', reason: 'unknown-attempt' } }];
if (ctx.status === 'saved') return [{ json: { ...base, action: 'done', articleId: ctx.article_id } }];
if (ctx.status === 'failed') return stop(ctx.error ?? 'failed');
if (ctx.status === 'model-done') return [{ json: { ...base, action: 'validate' } }];
if (ctx.status === 'calling') {
  // A call cannot outlive its window: live 120 s timeout, fake at most 60 s ('slow'), each plus a margin.
  // Older than that, the run that made it was interrupted. A live call may have been charged: never resent.
  const limit = ctx.mode === 'live' ? 130 : 75;
  if (Number(ctx.secondsSinceCallStarted) < limit) return stop('model-call-in-progress');
  return fail(ctx.mode === 'live' ? 'provider-uncertain' : 'interrupted-fake-call');
}
// pending: check the pinned input, then prepare the one call. A source that cannot be loaded right now
// stops the run with the attempt still pending (retry later); only a missing or corrupt version fails it.
if (pinned.loadError) return /^(not-found|hash-mismatch|invalid-bundle)/.test(pinned.loadError) ? fail(pinned.loadError) : stop(`source-unavailable: ${pinned.loadError}`);
const text = pinned.bundle.text;
if (!text.trim()) return fail('no-usable-text');
if (text.length > 60000) return fail('source-too-large');
const prompt = String(ctx.promptContent);
if (crypto.createHash('sha256').update(prompt, 'utf8').digest('hex') !== ctx.promptSha256) return fail('prompt-integrity');
const id = (/^id:\s*(\S+)/m.exec(prompt) || [])[1];
const system = ((/^# System\n([\s\S]*?)\n# User\n/m.exec(prompt) || [])[1] || '').trim();
const userTemplate = ((/^# User\n([\s\S]*)$/m.exec(prompt) || [])[1] || '').trim();
if (!id || !system || !userTemplate || `${id}@sha256:${ctx.promptSha256}` !== ctx.prompt_identity) return fail('prompt-malformed');
const b = pinned.bundle;
const values = { 'source.title': b.title, 'source.medium': b.medium, 'source.publishedAt': b.publishedAt ?? 'unknown', 'source.text': b.text };
let unknown = null;
// Values are inserted as data inside the prompt's <source> block; a source cannot close that block early.
const user = userTemplate.replace(/\{\{(source\.[a-zA-Z]+)\}\}/g, (m, k) => {
  if (!(k in values)) { unknown = k; return m; }
  return String(values[k]).replaceAll('</source>', '<\\/source>');
});
if (unknown) return fail(`prompt-malformed: unknown placeholder ${unknown}`);
const requestBody = { model: 'deepseek/deepseek-v4.1-flash', temperature: 0.2, max_tokens: 2000, response_format: { type: 'json_object' },
  reasoning: { enabled: false }, usage: { include: true }, messages: [{ role: 'system', content: system }, { role: 'user', content: user }] };
return [{ json: { ...base, action: 'call', requestBody } }];

const plan = $('Plan').first().json;
const begun = $json.begun;
if (plan.action !== 'call') return [{ json: { ...plan, route: plan.action } }];
if (begun === 'started') return [{ json: { ...plan, route: plan.mode } }];
if (begun === 'already-started') return [{ json: { ...plan, route: 'stop', reason: 'model-call-already-started' } }];
return [{ json: { ...plan, route: 'fail', reason: begun } }];

// The fake model: deterministic and free. It never describes real content.
const plan = $json;
const user = plan.requestBody.messages[1].content;
const title = ((/Title: (.*)/.exec(user) || [])[1] || 'the source').slice(0, 60);
const article = {
  title: `Fixture review of ${title}`.slice(0, 120),
  summary: `Fixture summary. The source is titled "${title}". This text is produced by the fake model for control proofs and never describes real content.`,
  critique: [
    { point: 'Fixture point one.', category: 'asserted', why_it_matters: 'Fixture reason one.' },
    { point: 'Fixture point two.', category: 'not-checked', why_it_matters: 'Fixture reason two.' },
    { point: 'Fixture point three.', category: 'established', why_it_matters: 'Fixture reason three.' },
  ],
  conclusion: 'Fixture conclusion.',
  warnings: ['Produced by the fake model.'],
};
// 'slow' holds the call open, so a run can be interrupted mid-call in tests.
if (plan.fakeBehaviour === 'slow') await new Promise((r) => setTimeout(r, 60000));
const raw = plan.fakeBehaviour === 'malformed' ? 'this is not JSON'
  : plan.fakeBehaviour === 'partial' ? JSON.stringify({ ...article, critique: [] }) : JSON.stringify(article);
return [{ json: { attempt: plan.attempt, model: 'fake/summary-critique-v1', raw, usage: { promptTokens: 0, completionTokens: 0, costUsd: 0, provider: 'fake' }, costUsd: 0, finishReason: 'stop' } }];

// Maps the provider's answer. Only a readable 2xx body is model output; nothing here is retried.
const plan = $('Route').first().json;
const r = $json;
const failWith = (reason) => [{ json: { attempt: plan.attempt, failReason: reason } }];
if (r.statusCode === 401 || r.statusCode === 403) return failWith(`unauthorised: provider returned ${r.statusCode}`);
if (r.statusCode === 429) return failWith('rate-limited: provider rate limit');
if (!(r.statusCode >= 200 && r.statusCode < 300)) return failWith(`provider-error: provider returned ${r.statusCode}`);
const body = typeof r.body === 'string' ? (() => { try { return JSON.parse(r.body); } catch { return null; } })() : r.body;
if (!body || typeof body !== 'object') return failWith('provider-uncertain: unreadable provider response');
const u = body.usage || {};
const cost = typeof u.cost === 'number' ? u.cost : null;
return [{ json: { attempt: plan.attempt, model: body.model ?? 'deepseek/deepseek-v4.1-flash', raw: body.choices?.[0]?.message?.content ?? '',
  usage: { promptTokens: u.prompt_tokens ?? null, completionTokens: u.completion_tokens ?? null, costUsd: cost, provider: body.provider ?? null },
  costUsd: cost, finishReason: body.choices?.[0]?.finish_reason ?? null } }];

// No response (timeout or lost connection): the request may have been accepted and charged. Never resent.
const plan = $('Route').first().json;
return [{ json: { attempt: plan.attempt, failReason: 'provider-uncertain: no response from the model provider' } }];

// ---- shared: article-v1 rules (doc/experiments/n8n-vs-mastra.md "Writing step") ----
const ARTICLE_KEYS = ['conclusion', 'critique', 'subtitle', 'summary', 'title', 'warnings'];
const LABEL = { asserted: 'Asserted by the author', established: 'Widely established', 'not-checked': 'Not checked' };
// Validates against article-v1 (strict keys, trimmed lengths) and returns the trimmed article, or a reason.
const checkArticle = (a) => {
  const str = (v, min, max) => typeof v === 'string' && v.trim().length >= min && v.trim().length <= max;
  if (!a || typeof a !== 'object' || Array.isArray(a)) return { error: 'schema' };
  const extra = Object.keys(a).find((k) => !ARTICLE_KEYS.includes(k));
  if (extra) return { error: extra };
  if (!str(a.title, 1, 120)) return { error: 'title' };
  if (a.subtitle !== undefined && !str(a.subtitle, 0, 200)) return { error: 'subtitle' };
  if (!str(a.summary, 1, 2500)) return { error: 'summary' };
  if (!Array.isArray(a.critique) || a.critique.length < 3 || a.critique.length > 8) return { error: 'critique' };
  for (let i = 0; i < a.critique.length; i++) {
    const c = a.critique[i];
    if (!c || typeof c !== 'object' || Array.isArray(c) || Object.keys(c).some((k) => !['point', 'category', 'why_it_matters'].includes(k))) return { error: `critique.${i}` };
    if (!str(c.point, 1, 600)) return { error: `critique.${i}.point` };
    if (!['asserted', 'established', 'not-checked'].includes(c.category)) return { error: `critique.${i}.category` };
    if (!str(c.why_it_matters, 1, 600)) return { error: `critique.${i}.why_it_matters` };
  }
  if (!str(a.conclusion, 1, 1200)) return { error: 'conclusion' };
  if (!Array.isArray(a.warnings) || a.warnings.length > 10 || !a.warnings.every((w) => str(w, 0, 300))) return { error: 'warnings' };
  const article = { title: a.title.trim(), summary: a.summary.trim(),
    critique: a.critique.map((c) => ({ point: c.point.trim(), category: c.category, why_it_matters: c.why_it_matters.trim() })),
    conclusion: a.conclusion.trim(), warnings: a.warnings.map((w) => w.trim()) };
  if (a.subtitle !== undefined) article.subtitle = a.subtitle.trim();
  return { article };
};
// Model text is prose: anything the draft service's converter would reject is refused before saving.
const unsupportedMarkdown = (a) => {
  const fields = [a.title, a.subtitle ?? '', a.summary, a.conclusion, ...a.warnings, ...a.critique.flatMap((c) => [c.point, c.why_it_matters])];
  for (const f of fields) {
    if (/<\/?[a-zA-Z][^>]*>/.test(f)) return 'html';
    if (/!\[/.test(f)) return 'image';
    if (/```|`/.test(f)) return 'code';
    if (/\]\((?!https:\/\/)/.test(f)) return 'non-https-link';
    for (const line of f.split('\n')) {
      const t = line.trimStart();
      if (/^#{1,6}\s/.test(t)) return 'heading';
      if (t.startsWith('>')) return 'blockquote';
      if (t.startsWith('|')) return 'table';
      if (/^(-{3,}|\*{3,}|_{3,})\s*$/.test(t)) return 'rule';
    }
  }
  return null;
};
// Deterministic Markdown per the contract's rendering rules.
const renderArticle = (a) => {
  const parts = [a.summary.trim(), '## Problems with the argument',
    a.critique.map((c) => `- **${LABEL[c.category]}:** ${c.point.trim()} Why it matters: ${c.why_it_matters.trim()}`).join('\n'),
    a.conclusion.trim()];
  const warnings = a.warnings.map((w) => w.trim()).filter(Boolean);
  if (warnings.length) parts.push(`*Note: ${warnings.join(' ')}*`);
  return `${parts.join('\n\n')}\n`;
};
const words = (s) => s.replace(/[*_#`>[\]()-]/g, ' ').split(/\s+/).filter(Boolean).length;
// Advisory length guidance: counts and a warning, never a rejection.
const lengthGuidance = (a) => {
  const summaryWords = words(a.summary), conclusionWords = words(a.conclusion);
  return { summaryWords, conclusionWords, warning: summaryWords < 120 || summaryWords > 250 || conclusionWords > 120 ? 'length-outside-guidance' : null };
};
// ---- end shared ----
// Validates, renders and identifies the article, or explains the failure. Runs for every route.
const crypto = require('crypto');
const r = $('Route').first().json;
const out = (o) => [{ json: { attempt: r.attempt, trace: r.trace, ...o } }];
if (r.route === 'stop') return out({ outcome: 'stop', reason: r.reason });
if (r.route === 'done') return out({ outcome: 'done', articleId: r.articleId });
if (r.route === 'fail') return out({ outcome: 'fail', reason: r.reason });
let raw;
if (r.route === 'validate') raw = $('Read attempt').first().json.result.raw_output;
else {
  if ($json.fail_reason) return out({ outcome: 'fail', reason: $json.fail_reason });
  if ($json.saved !== true) return out({ outcome: 'stop', reason: 'model-output-not-saved' });
  raw = $json.raw;
}
let parsed;
try { parsed = JSON.parse(raw); } catch { return out({ outcome: 'fail', reason: 'invalid-model-output: not JSON' }); }
const checked = checkArticle(parsed);
if (checked.error) return out({ outcome: 'fail', reason: `invalid-model-output: ${checked.error}` });
const article = checked.article;
const unsupported = unsupportedMarkdown(article);
if (unsupported) return out({ outcome: 'fail', reason: `invalid-model-output: unsupported-markdown (${unsupported})` });
const length = lengthGuidance(article);
if (length.warning && !article.warnings.includes(length.warning) && article.warnings.length < 10) article.warnings.push(length.warning);
const markdown = renderArticle(article);
const articleId = `${r.attempt}/article@sha256:${crypto.createHash('sha256').update(markdown, 'utf8').digest('hex')}`;
// The source's own evidence limitations (for example, a recording's description used instead of a
// transcript) are kept with the saved article, from the pinned version, not from the model.
const src = r.trace ?? {};
return out({ outcome: 'save', articleId, title: article.title, subtitle: article.subtitle ?? null, markdown,
  articleJson: { ...article, lengthGuidance: length, source: { version: src.sourceVersion ?? null, textSource: src.textSource ?? null,
    medium: src.medium ?? null, warnings: src.sourceWarnings ?? [] } } });

// The run's visible result: outcome, article, and the trace of exactly what was used.
const v = $('Validate and render').first().json;
const o = $json.outcome ?? {};
const status = v.outcome === 'save' || v.outcome === 'done' ? 'saved' : v.outcome === 'fail' ? 'failed' : 'stopped';
return [{ json: { attempt: v.attempt, status, articleId: o.articleId ?? v.articleId ?? null, alreadySaved: o.alreadySaved ?? v.outcome === 'done',
  error: v.outcome === 'fail' || v.outcome === 'stop' ? v.reason : null, trace: v.trace ?? null } }];
